class FileLogger {
    private logFilePath: string;
    private fs: any;


    constructor(filename: string = "install.log") {

        const path = require("path");

        const fs = require("fs");
        this.fs = fs;

        this.logFilePath = path.join(".", filename);
        try {
            this.fs.unlinkSync(this.logFilePath);
        } catch (err) {

        }

    }

    log(message: string): void {
        const timestamp = new Date().toISOString();
        const logEntry = `[${timestamp}] ${message}\n`;
        this.fs.appendFile(this.logFilePath, logEntry, () => {  });

    }



    generateLogHandler(ctx: HookContext): (message: string) => void {
        const oldLog = ctx.log.bind(ctx);
        return (message: string) => {
            oldLog(message);
            this.log(message);
            console.log(message);
        }
    }

    getLogPath(): string {
        return this.logFilePath;
    }
}

type RequestTemplate = {
    id: string;
    urlpath: string;
    requestInit: {
        method?: NonNullable<RequestInit["method"]>;
        headers?: Record<string, string>;
        body?: unknown;
    };
};



function cloneJsonValue<T>(value: T): T {
    if (value === undefined) {
        return value;
    }
    return JSON.parse(JSON.stringify(value)) as T;
}

function getRequestTemplate(typedRequestToSend: RequestTemplate[], templateId: string): RequestTemplate {
    const template = typedRequestToSend.find((entry) => entry.id === templateId);
    if (!template) {
        throw new Error(`Missing request template '${templateId}' in request_to_sent.jsonc`);
    }
    return template;
}

function buildRequestInit(
    baseHeaders: Record<string, string>,
    template: RequestTemplate,
    bodyOverride?: unknown,
): RequestInit {
    const sourceBody = bodyOverride !== undefined ? bodyOverride : template.requestInit.body;
    const requestInit: RequestInit = {
        method: template.requestInit.method ?? "GET",
        headers: {
            ...baseHeaders,
            ...(template.requestInit.headers ?? {}),
        },
    };

    if (sourceBody !== undefined) {
        requestInit.body = JSON.stringify(sourceBody);
    }

    return requestInit;
}

interface ApiKey {
  Id: string;
  AccessToken: string;
  AppName: string;
  DateCreated: string;
}

interface AuthResponse {
  AccessToken: string;
  User: {
    Id: string;
    Policy: { IsAdministrator: boolean };
  };
}

class JellyfinClient {
  private baseUrl: string;
  private token: string | null = null;

  constructor(baseUrl: string) {

    this.baseUrl = baseUrl.replace(/\/$/, '');
  }



  private getHeaders(token?: string): Record<string, string> {
    let authHeader = 'MediaBrowser Client="NodeTSApp", Device="Server", DeviceId="unique-device-id", Version="1.0.0"';
    if (token) {
      authHeader += `, Token="${token}"`;
    }
    return {
      'Authorization': authHeader,
      'Content-Type': 'application/json',
    };
  }



  async login(username: string, pw: string): Promise<string> {
    const response = await fetch(`${this.baseUrl}/Users/AuthenticateByName`, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify({ Username: username, Pw: pw }),
    });

    if (!response.ok) {
      throw new Error(`Auth failed with status ${response.status}`);
    }

    const data: AuthResponse = await response.json();

    if (!data.User.Policy.IsAdministrator) {
      throw new Error('Authenticated user must be an administrator to manage API keys.');
    }

    this.token = data.AccessToken;
    return this.token;
  }



  async getApiKeys(): Promise<ApiKey[]> {
    if (!this.token) throw new Error('Not authenticated. Call login() first.');

    const response = await fetch(`${this.baseUrl}/Auth/Keys`, {
      method: 'GET',
      headers: this.getHeaders(this.token),
    });

    if (!response.ok) throw new Error(`Failed to fetch keys: ${response.status}`);

    const data = await response.json();
    return data.Items ?? [];
  }



  async createApiKey(appName: string): Promise<void> {
    if (!this.token) throw new Error('Not authenticated. Call login() first.');

    const url = `${this.baseUrl}/Auth/Keys?app=${encodeURIComponent(appName)}`;
    const response = await fetch(url, {
      method: 'POST',
      headers: this.getHeaders(this.token),
    });

    if (!response.ok) throw new Error(`Failed to create key: ${response.status}`);
  }
}
async function getJellyfinApiKey(ctx: HookContext, JELLYFIN_URL: string, JELLYFIN_USERNAME: string, JELLYFIN_PASSWORD: string): Promise<string | null> {
  const jellyfin = new JellyfinClient(JELLYFIN_URL);
 let apiKeyJelly: string | null = null;
  try {


    await jellyfin.login(JELLYFIN_USERNAME, JELLYFIN_PASSWORD);
    ctx.log('Successfully authenticated!');


    ctx.log('Creating new API key...');
    try {

        await jellyfin.createApiKey('radarr-integration');
        ctx.log('API key created successfully.');
    } catch (error) {
        ctx.log(`Error creating API key: ${error}`);
    }



    ctx.log('Fetching all active API keys...');
    const keys = await jellyfin.getApiKeys();

    apiKeyJelly = keys.find(key => key.AppName === 'radarr-integration')?.AccessToken || null;
    if (!apiKeyJelly) {
        ctx.log('Failed to retrieve the newly created jellyfin API key.');
    }
  } catch (error) {
    ctx.log(`Error: ${error}`);
  }
  return apiKeyJelly;
}

